import{_ as s,o as a,c as e,a2 as t}from"./chunks/framework.CvydjLy7.js";const c=JSON.parse('{"title":"11.7 Buildpacks：不写 Dockerfile 的路线","description":"","frontmatter":{"title":"11.7 Buildpacks：不写 Dockerfile 的路线"},"headers":[{"level":3,"title":"几个默认值","slug":"几个默认值","link":"#几个默认值","children":[]},{"level":3,"title":"和 Dockerfile 路线的取舍","slug":"和-dockerfile-路线的取舍","link":"#和-dockerfile-路线的取舍","children":[]}],"relativePath":"ch11/07.md","filePath":"ch11/07.md","lastUpdated":1789497795000}'),l={name:"ch11/07.md"};function d(n,i,p,k,h,r){return a(),e("div",null,[...i[0]||(i[0]=[t(`<h1 id="_11-7-buildpacks-不写-dockerfile-的路线" tabindex="-1">11.7 Buildpacks：不写 Dockerfile 的路线 <a class="header-anchor" href="#_11-7-buildpacks-不写-dockerfile-的路线" aria-label="Permalink to &quot;11.7 Buildpacks：不写 Dockerfile 的路线&quot;">​</a></h1><p>前面那条路线需要自己维护 Dockerfile、自己处理基础镜像更新。另一条路线是 Cloud Native Buildpacks（CNB）：给插件一条命令，它自己分析项目、选 JDK、分层、生成镜像。</p><div class="language-shell vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">shell</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">$</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> mvn</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> spring-boot:build-image</span></span></code></pre></div><p>4.1.1 的默认 builder 是：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>paketobuildpacks/builder-noble-java-tiny:latest</span></span></code></pre></div><p>生成的镜像名由项目坐标推导，默认是 <code>docker.io/library/\${artifactId}:\${version}</code>，对应本工程就是 <code>docker.io/library/activity-server:1.0.0</code>。</p><p>这一节的命令与默认值来自 4.1.1 的插件文档。构建时插件要按 builder 元数据拉取 builder 与 run image（本机实测 builder 镜像 858MB），这一步依赖镜像仓库的可达性，在配置好仓库代理的环境里可以直接跑通。</p><h3 id="几个默认值" tabindex="-1">几个默认值 <a class="header-anchor" href="#几个默认值" aria-label="Permalink to &quot;几个默认值&quot;">​</a></h3><table tabindex="0"><thead><tr><th>参数</th><th>默认值</th><th>说明</th></tr></thead><tbody><tr><td><code>builder</code></td><td><code>paketobuildpacks/builder-noble-java-tiny:latest</code></td><td>可选 <code>jammy-base</code>、<code>jammy-full</code> 等</td></tr><tr><td><code>name</code></td><td><code>docker.io/library/\${artifactId}:\${version}</code></td><td>用 <code>spring-boot.build-image.imageName</code> 覆盖</td></tr><tr><td><code>pullPolicy</code></td><td><code>ALWAYS</code></td><td>每次构建都拉 builder，<code>NEVER</code> 可跳过</td></tr><tr><td><code>createdDate</code></td><td>固定日期</td><td>固定的时间戳，让镜像可复现</td></tr><tr><td><code>trustBuilder</code></td><td>视 builder 而定</td><td>只有官方列出的那几个 builder 默认为可信</td></tr></tbody></table><p>绑定到 <code>package</code> 阶段时要换成 <code>build-image-no-fork</code>：</p><div class="language-xml vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">xml</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&lt;</span><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">plugin</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&gt;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  &lt;</span><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">groupId</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&gt;org.springframework.boot&lt;/</span><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">groupId</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&gt;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  &lt;</span><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">artifactId</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&gt;spring-boot-maven-plugin&lt;/</span><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">artifactId</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&gt;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  &lt;</span><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">executions</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&gt;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    &lt;</span><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">execution</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&gt;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">      &lt;</span><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">goals</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&gt;&lt;</span><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">goal</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&gt;build-image-no-fork&lt;/</span><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">goal</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&gt;&lt;/</span><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">goals</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&gt;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    &lt;/</span><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">execution</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&gt;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  &lt;/</span><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">executions</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&gt;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&lt;/</span><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">plugin</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&gt;</span></span></code></pre></div><p><code>build-image</code> 会 fork 一次生命周期来确保 <code>package</code> 先跑完，适合命令行调用；在构建配置里绑定执行时应该用 <code>build-image-no-fork</code>，否则会多跑一轮。</p><h3 id="和-dockerfile-路线的取舍" tabindex="-1">和 Dockerfile 路线的取舍 <a class="header-anchor" href="#和-dockerfile-路线的取舍" aria-label="Permalink to &quot;和 Dockerfile 路线的取舍&quot;">​</a></h3><p>Buildpacks 的优点是省事：不写 Dockerfile，基础镜像的安全更新由 builder 负责，分层规则由 Paketo 的 buildpack 决定。JVM 参数、内存比例、<code>layers.idx</code> 这些它都认识。</p><p>代价是控制力弱一些。想调整基础镜像里的系统包、想精确控制层的划分、想在构建阶段做点别的事（比如生成 CDS 归档），Buildpacks 给的余地比 Dockerfile 小。构建过程也更慢——它要拉 builder 镜像、跑完整的 buildpack 生命周期。</p><p>还有一点：<strong>buildpacks 会改写应用产物的元数据</strong>（比如文件的最后修改时间），用来做可复现构建和缓存。官方文档提醒，如果你的代码在运行期依赖这些元数据，行为会变。静态资源的缓存就是一处，必要时用 <code>spring.web.resources.cache.use-last-modified</code> 关掉。</p><p>选择上可以这样看：<strong>镜像构建流程统一走 CNB 的平台</strong>（比如团队已经有 CNB 的 CI 集成）就用 Buildpacks；需要精细控制镜像内容、或者构建阶段有自定义步骤，就用 Dockerfile。</p><hr>`,18)])])}const E=s(l,[["render",d]]);export{c as __pageData,E as default};
